from pathlib import Path
import py_compile, subprocess, yaml
files=list(Path('.github/scripts').glob('*functionfix*.py'))+[Path('.github/scripts/prepare_new_ui_source.py')]
for path in files: py_compile.compile(str(path),doraise=True)
workflow=yaml.safe_load(Path('.github/workflows/ui-v76-build.yml').read_text())
assert workflow['concurrency']['cancel-in-progress'] is False
count=0
for job in workflow['jobs'].values():
 for step in job.get('steps',[]):
  if 'run' in step:
   subprocess.run(['bash','-n'],input=step['run'],text=True,check=True)
   count+=1
for name in ('hetu-root.sh','hetu-autostart.sh'):
 subprocess.run(['sh','-n','android-app/app/src/main/assets/'+name],check=True)
print('Python files:',len(files),'workflow bash snippets:',count,'root/autostart sh syntax: OK')
